<?php
declare(strict_types=1);require_once __DIR__.'/../src/db.php';require_once __DIR__.'/../src/auth.php';require_once __DIR__.'/../src/ui.php';require_teacher_or_admin();$pdo=db();
$stats=['pending'=>(int)$pdo->query("SELECT COUNT(*) FROM student_activities WHERE status='pending'")->fetchColumn(),'completed'=>(int)$pdo->query("SELECT COUNT(*) FROM student_activities WHERE status='completed'")->fetchColumn(),'avg'=>(float)$pdo->query("SELECT COALESCE(AVG(score),0) FROM student_activities WHERE status='completed' AND score IS NOT NULL")->fetchColumn(),'xp'=>(int)$pdo->query("SELECT COALESCE(SUM(xp_earned),0) FROM student_activities WHERE status='completed'")->fetchColumn()];
$rows=$pdo->query("SELECT sa.id,sa.status,sa.assigned_at,sa.completed_at,sa.score,sa.xp_earned,s.id student_id,s.name student_name,a.title,a.activity_type,a.skill,a.level,a.xp_reward,a.estimated_minutes FROM student_activities sa JOIN students s ON s.id=sa.student_id JOIN activities a ON a.id=sa.activity_id ORDER BY CASE WHEN sa.status='pending' THEN 0 ELSE 1 END,COALESCE(sa.completed_at,sa.assigned_at) DESC LIMIT 120")->fetchAll();
$pageTitle='Atividades';$pageSubtitle='Exercícios atribuídos e resultados vinculados aos alunos.';require __DIR__.'/../templates/header.php';?>
<section class="cards"><article class="card metric-card"><div><div class="label">Pendentes</div><div class="metric"><?=$stats['pending']?></div><div class="metric-sub">Aguardando conclusão</div></div><div class="metric-icon"><?=ui_icon('activities')?></div></article><article class="card metric-card"><div><div class="label">Concluídas</div><div class="metric"><?=$stats['completed']?></div><div class="metric-sub">Histórico total</div></div><div class="metric-icon"><?=ui_icon('progress')?></div></article><article class="card metric-card"><div><div class="label">Média das notas</div><div class="metric"><?=number_format($stats['avg'],0)?>%</div><div class="metric-sub">Atividades com avaliação</div></div><div class="metric-icon"><?=ui_icon('reports')?></div></article><article class="card metric-card"><div><div class="label">XP conquistado</div><div class="metric"><?=$stats['xp']?></div><div class="metric-sub">Recompensas concluídas</div></div><div class="metric-icon"><?=ui_icon('sparkles')?></div></article></section>
<section class="panel"><div class="panel-head"><div><h2>Histórico de atividades</h2><p>O nome do aluno abre a ficha individual correspondente.</p></div></div><?php if(!$rows):?><div class="empty-state"><div class="empty-state-icon"><?=ui_icon('activities')?></div><h3>Nenhuma atividade registrada</h3><p>As atividades geradas para os alunos serão exibidas aqui.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Atividade</th><th>Nível</th><th>Skill</th><th>Status</th><th>Nota</th><th>XP</th><th>Data</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><a class="table-link" href="/student.php?id=<?=e($row['student_id'])?>"><strong><?=e($row['student_name'])?></strong></a></td><td><strong><?=e($row['title'])?></strong><div class="label"><?=e(ui_status_label($row['activity_type']))?> · <?= (int)($row['estimated_minutes']??0)?> min</div></td><td><span class="badge <?=e(ui_level_class($row['level']))?>"><?=e($row['level']??'—')?></span></td><td><?=e($row['skill']??'—')?></td><td><span class="badge <?=e(ui_status_class($row['status']))?>"><?=e(ui_status_label($row['status']))?></span></td><td><?=$row['score']!==null?number_format((float)$row['score'],0).'%':'—'?></td><td><?= (int)$row['xp_earned']?></td><td><?=e(ui_date($row['completed_at']?:$row['assigned_at']))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php require __DIR__.'/../templates/footer.php';?>
